    for (int i = 0; i < choices.size(); ++i) combo.addItem(choices[i], i + 1); combo.setColour(juce::ComboBox::backgroundColourId, juce::Colour::fromRGB(12, 12, 19)); combo.setColour(juce::ComboBox::outlineColourId, panelEdge); combo.setColour(juce::ComboBox::textColourId, juce::Colours::white.withAlpha(0.82f)); combo.setColour(juce::ComboBox::arrowColourId, accent); addAndMakeVisible(combo);
