    loadSampleButton.onClick = [this] { sampleChooser = std::make_unique<juce::FileChooser>("Load sample", juce::File(), "*.wav;*.aif;*.aiff;*.flac;*.mp3"); sampleChooser->launchAsync(juce::FileBrowserComponent::openMode | juce::FileBrowserComponent::canSelectFiles, [this](const juce::FileChooser& chooser) { if (processor.loadSampleFile(chooser.getResult())) refreshSampleName(); }); };
