        const auto s = juce::String(i + 1); lfoRates[i] = std::make_unique<ParamKnob>(p.parameters, "lfo" + s + "_rate", "LFO " + s + " Hz"); lfoModes[i] = std::make_unique<ParamCombo>(p.parameters, "lfo" + s + "_mode", "LFO " + s, juce::StringArray { "Free", "Retrig", "One Shot" }); macros[i] = std::make_unique<ParamKnob>(p.parameters, "macro" + s, "Macro " + s); modSources[i] = std::make_unique<ParamCombo>(p.parameters, "mod" + s + "_source", "Source " + s, modulationSources); modDestinations[i] = std::make_unique<ParamCombo>(p.parameters, "mod" + s + "_dest", "Destination " + s, modulationDestinations); modDepths[i] = std::make_unique<ParamKnob>(p.parameters, "mod" + s + "_depth", "Depth " + s);
